# Generated by Forge scripts/export_workspace_science.py.
# fmt: off
"""Deterministic private scientific archive; bytes remain in artifact custody.

The caller retains these bytes through the existing archive authority, verifies
its receipt, then saves a Snapshot referring to that exact archive. This module
does not release data, extend retention or claim complete execution capture.
"""

import hashlib
import json
from collections.abc import Callable, Sequence
from datetime import datetime

from pydantic import ValidationError

from .contracts import (
    ExactReference,
    ForgeError,
    Scope,
    canonical_bytes,
    contract_digest,
)
from .operations import RecordRevision, RevisionReference, revision_reference
from .operations_v2 import RecordRevisionV2, ScientificRevision, parse_revision
from .records import Artifact, Snapshot

MAX_ARCHIVE_BYTES = 4 * 1024 * 1024
ARCHIVE_V1 = "forge.private-archive.v1"
ARCHIVE_V2 = "forge.private-archive.v2"
# v3 adds each record's RevisionReference (decision 0001). v1/v2 stay
# payload-bound: their selection cannot distinguish altered provenance.
ARCHIVE_V3 = "forge.private-archive.v3"
ARCHIVE_V4 = "forge.private-archive.v4"
ARCHIVE_VERSIONS = (ARCHIVE_V1, ARCHIVE_V2, ARCHIVE_V3, ARCHIVE_V4)
RetainedRevision = Callable[[Scope, ExactReference], RevisionReference]


def _artifact_objects(records: Sequence[ScientificRevision]) -> tuple[dict, ...]:
    """Derive byte ancestry solely from exact selected Artifact declarations."""
    objects = []
    for item in records:
        record = parse_revision(item.model_dump(mode="json"))
        if (
            record.reference.authority != "forge"
            or record.reference.kind != record.payload.kind
            or record.reference.digest_sha256 != contract_digest(record.payload)
        ):
            raise ForgeError("reference_conflict", "artifact record digest differs")
        artifact = record.payload
        if not isinstance(artifact, Artifact) or artifact.delivery is None:
            continue
        if artifact.object.kind != "object" or artifact.manifest.kind != "manifest":
            raise ForgeError(
                "reference_conflict", "canonical Artifact byte refs required"
            )
        objects.append(
            {
                "artifact": record.reference.model_dump(mode="json"),
                "object": artifact.object.model_dump(mode="json"),
            }
        )
    return tuple(sorted(objects, key=canonical_bytes))


def scientific_archive_sources(
    records: Sequence[ScientificRevision], *, schema_version: str = ARCHIVE_V1
) -> tuple[ExactReference, ...]:
    """Select record refs and, in v2 only, their retained native byte refs.

    See docs/contracts.md. These refs preserve ancestry, never current access
    or retention authority. The custodian still verifies each selected object.
    """
    if not isinstance(schema_version, str) or schema_version not in ARCHIVE_VERSIONS:
        raise ForgeError("archive_version_unsupported", "unsupported private archive")
    if schema_version != ARCHIVE_V4 and any(
        isinstance(item, RecordRevisionV2) for item in records
    ):
        raise ForgeError(
            "archive_version_unsupported", "v2 record envelopes require archive v4"
        )
    sources = {item.reference for item in records}
    if schema_version != ARCHIVE_V1:
        sources.update(
            ExactReference.model_validate(item["object"])
            for item in _artifact_objects(records)
        )
    if not sources or len(sources) > 1024:
        raise ForgeError("selection_invalid", "select 1 through 1024 exact sources")
    return tuple(sorted(sources, key=canonical_bytes))


def scientific_archive(
    scope: Scope,
    records: Sequence[ScientificRevision],
    *,
    cutoff_at: datetime,
    gaps: tuple[str, ...] = (),
    schema_version: str = ARCHIVE_V1,
) -> bytes:
    if not records or len(records) > 1024:
        raise ForgeError("selection_invalid", "select 1 through 1024 exact revisions")
    try:
        records = tuple(
            parse_revision(item.model_dump(mode="json")) for item in records
        )
    except ValidationError as error:
        raise ForgeError(
            "reference_conflict", "selected record schema is invalid"
        ) from error
    if cutoff_at.tzinfo is None:
        raise ForgeError("selection_invalid", "archive cutoff needs a timezone")
    identities = set()
    ordered = sorted(
        records,
        key=lambda record: (record.reference.record_id, record.reference.revision),
    )
    for record in ordered:
        if record.scope != scope or record.recorded_at > cutoff_at:
            raise ForgeError("selection_invalid", "record differs from scope or cutoff")
        if (
            record.reference.authority != "forge"
            or record.reference.kind != record.payload.kind
            or record.reference.digest_sha256 != contract_digest(record.payload)
        ):
            raise ForgeError(
                "reference_conflict", "record differs from exact source bytes"
            )
        identity = (record.reference.record_id, record.reference.revision)
        if identity in identities:
            raise ForgeError("selection_invalid", "duplicate selected revision")
        identities.add(identity)
    document = {
        "schema_version": schema_version,
        "scope": scope.model_dump(mode="json"),
        "cutoff_at": cutoff_at.isoformat(),
        "capture_completeness": "partial" if gaps else "complete",
        "gaps": gaps,
        "records": [record.model_dump(mode="json") for record in ordered],
    }
    scientific_archive_sources(ordered, schema_version=schema_version)
    if schema_version != ARCHIVE_V1:
        document["artifact_objects"] = _artifact_objects(ordered)
    if schema_version in {ARCHIVE_V3, ARCHIVE_V4}:
        document["revisions"] = [
            revision_reference(record).model_dump(mode="json") for record in ordered
        ]
    encoded = canonical_bytes(document)
    if len(encoded) > MAX_ARCHIVE_BYTES:
        raise ForgeError("archive_too_large", "scientific archive exceeds 4 MiB")
    return encoded


def scientific_archive_revisions(
    records: Sequence[ScientificRevision],
) -> tuple[RevisionReference, ...]:
    """Full-document identities a v3 consumer pins alongside Snapshot.sources."""
    return tuple(
        sorted((revision_reference(record) for record in records), key=canonical_bytes)
    )


def verify_scientific_archive(
    content: bytes,
    scope: Scope,
    snapshot: Snapshot,
    *,
    retained: RetainedRevision | None = None,
    require_revisions: bool = False,
) -> tuple[ScientificRevision, ...]:
    """Reopen exact retained scientific bytes without the original writer.

    See docs/contracts.md. This verifies the scientific record archive format;
    native execution archives retain their separately owned capture validators.
    Current byte access and retention remain the archive custodian's decision.
    ``retained`` resolves each v3 record to the canonical store's
    RevisionReference; a re-frozen archive with altered provenance refuses.
    ``require_revisions`` refuses payload-bound v1/v2 archives.
    """
    snapshot = Snapshot.model_validate(snapshot.model_dump(mode="json"))
    if len(content) > MAX_ARCHIVE_BYTES:
        raise ForgeError("archive_too_large", "scientific archive exceeds 4 MiB")
    if hashlib.sha256(content).hexdigest() != snapshot.archive.digest_sha256:
        raise ForgeError("reference_conflict", "retained archive digest differs")
    try:
        document = json.loads(content)
        if not isinstance(document, dict) or not isinstance(
            document.get("records"), list
        ):
            raise ValueError("record archive required")
        schema_version = document.get("schema_version")
        decoder = (
            parse_revision
            if schema_version == ARCHIVE_V4
            else RecordRevision.model_validate
        )
        records = tuple(decoder(item) for item in document["records"])
        expected = scientific_archive(
            scope,
            records,
            cutoff_at=snapshot.cutoff_at,
            gaps=snapshot.gaps,
            schema_version=schema_version,
        )
    except (ValueError, UnicodeDecodeError, ValidationError) as error:
        if isinstance(error, ForgeError):
            raise
        raise ForgeError(
            "archive_invalid", "retained scientific archive is invalid"
        ) from error
    if content != expected:
        raise ForgeError(
            "reference_conflict", "archive differs from frozen scope/cutoff"
        )
    selected = scientific_archive_sources(records, schema_version=schema_version)
    if len(selected) != len(snapshot.sources) or set(selected) != set(snapshot.sources):
        raise ForgeError(
            "reference_conflict", "archive differs from frozen source selection"
        )
    if schema_version not in {ARCHIVE_V3, ARCHIVE_V4}:
        if require_revisions or retained is not None:
            raise ForgeError(
                "archive_version_unsupported",
                "payload-bound archive cannot prove revision provenance",
            )
        return records
    if retained is not None:
        for record in records:
            if retained(scope, record.reference) != revision_reference(record):
                raise ForgeError(
                    "reference_conflict",
                    "archive revision differs from retained provenance",
                )
    return records
